using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway gateway;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = provider.BaseAddress };
        gateway = new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
        Assert.Equal(3, root.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_status_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        var outcome = await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_status_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        var outcome = await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"x1","status":"approved","risk":{"score":3}}""");

        var outcome = await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refused_payment_402_is_declined_whatever_the_body()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        var outcome = await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{}""")]
    [InlineData("""null""")]
    public async Task Anything_other_than_an_approved_status_is_never_approved(string body)
    {
        provider.Respond(200, body);

        var outcome = await gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_are_raised_not_treated_as_a_decision(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        var ex = await Assert.ThrowsAsync<HttpRequestException>(() =>
            gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));

        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_malformed_body_on_success_is_raised()
    {
        provider.Respond(200, "not json");

        await Assert.ThrowsAsync<JsonException>(() =>
            gateway.AuthorizeAsync("A", new Money(1, "EUR"), CancellationToken.None));
    }

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }

    private sealed record Received(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<Received> requests = [];
        private int status = 200;
        private string body = "{}";

        public FakeProvider()
        {
            for (var attempt = 0; ; attempt++)
            {
                var port = Random.Shared.Next(20000, 60000);
                var prefix = $"http://127.0.0.1:{port}/";
                var candidate = new HttpListener();
                candidate.Prefixes.Add(prefix);
                try
                {
                    candidate.Start();
                    listener = candidate;
                    BaseAddress = new Uri(prefix);
                    break;
                }
                catch (HttpListenerException) when (attempt < 10) { candidate.Close(); }
            }
            _ = Task.Run(Loop);
        }

        public Uri BaseAddress { get; }

        public IReadOnlyList<Received> Requests { get { lock (requests) return requests.ToList(); } }

        public void Respond(int statusCode, string responseBody) { status = statusCode; body = responseBody; }

        private async Task Loop()
        {
            while (listener.IsListening)
            {
                HttpListenerContext ctx;
                try { ctx = await listener.GetContextAsync(); }
                catch { return; }

                using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
                var received = new Received(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath,
                    ctx.Request.ContentType, await reader.ReadToEndAsync());
                lock (requests) requests.Add(received);

                var bytes = Encoding.UTF8.GetBytes(body);
                ctx.Response.StatusCode = status;
                ctx.Response.ContentType = "application/json";
                ctx.Response.ContentLength64 = bytes.Length;
                await ctx.Response.OutputStream.WriteAsync(bytes);
                ctx.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
